import{_ as a,o as e,c as r,a2 as o}from"./chunks/framework.DSoq407f.js";const u=JSON.parse('{"title":"控制台总览","description":"","frontmatter":{},"headers":[],"relativePath":"console/overview.md","filePath":"console/overview.md","lastUpdated":1786543008000}'),i={name:"console/overview.md"};function l(s,t,n,d,h,c){return e(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="控制台总览" tabindex="-1">控制台总览 <a class="header-anchor" href="#控制台总览" aria-label="Permalink to &quot;控制台总览&quot;">​</a></h1><blockquote><p><strong>你会学到</strong>：用户控制台能做什么、各功能模块概览。</p></blockquote><p>用户控制台是**租户（最终用户）**使用的自助界面，登录入口在控制台登录页。在这里管理你自己的机器人、插件、订阅。</p><h2 id="核心模块" tabindex="-1">核心模块 <a class="header-anchor" href="#核心模块" aria-label="Permalink to &quot;核心模块&quot;">​</a></h2><table tabindex="0"><thead><tr><th>模块</th><th>作用</th></tr></thead><tbody><tr><td><a href="./bots">机器人管理</a></td><td>创建、配置、监控机器人</td></tr><tr><td><a href="./plugins">插件中心</a></td><td>浏览、购买、安装插件</td></tr><tr><td><a href="./subscriptions">我的订阅</a></td><td>查看订阅、续费</td></tr><tr><td><a href="./account">账户与充值</a></td><td>余额、充值、账单</td></tr><tr><td><a href="./openapi">Open API</a></td><td>管理 API Key、二次集成</td></tr></tbody></table><h2 id="上手流程" tabindex="-1">上手流程 <a class="header-anchor" href="#上手流程" aria-label="Permalink to &quot;上手流程&quot;">​</a></h2><p>新用户首次使用，典型路径：</p><ol><li><strong>充值 / 购买订阅</strong>：在<a href="./account">账户与充值</a>充值余额，或在<a href="./subscriptions">我的订阅</a>购买套餐。</li><li><strong>创建机器人</strong>：在<a href="./bots">机器人管理</a>创建机器人，选择平台、填凭证。</li><li><strong>安装插件</strong>：在<a href="./plugins">插件中心</a>浏览并安装需要的插件，绑定到机器人。</li><li><strong>配置插件</strong>：在机器人设置里配置各插件的参数。</li><li><strong>启动机器人</strong>：机器人开始接收消息、响应。</li></ol><h2 id="资源配额" tabindex="-1">资源配额 <a class="header-anchor" href="#资源配额" aria-label="Permalink to &quot;资源配额&quot;">​</a></h2><p>你的资源（机器人数量、插件数量、可用平台）由<strong>订阅套餐</strong>决定：</p><ul><li>套餐配额用完，无法新建机器人 / 装插件。</li><li>订阅过期，资源降级（停用，不删数据），续费恢复。</li><li>升级套餐立即获得更高配额。</li></ul><p>详见<a href="./subscriptions">我的订阅</a>。</p><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li>开始创建机器人 → <a href="./bots">机器人管理</a></li><li>找插件装 → <a href="./plugins">插件中心</a></li></ul>',14)])])}const f=a(i,[["render",l]]);export{u as __pageData,f as default};
